    return {
      scenario: scenarioName,
      agent,
      lab_fork: lab || null,
      passed: false,
      checks: [],
      summary: `Runner error: ${errMsg.slice(0, 500)}`,
      agent_status: "error",
      duration,
      gym_root: SCENARIOS_DIR,
    };
